                    count = vRefundedTo.Decode(queue.ToArray());
                    for (int i = 0; i < Convert.ToInt32(count); i++) { queue.Dequeue(); }
                    var valueRefundedTo = vRefundedTo.ToValue();
                    if (valueRefundedTo is Algorand.Address vRefundedToValue) { ret.RefundedTo = vRefundedToValue; }
                    return ret;

                }

            }

        }

