        ///no other call can consume the same sendToAnyone. Returns the new wallet id read from that call's
        ///ABI return.
        ///
        ///`mbrPayment` pays this app for the subject entry and the gift box. Its sender is the gift box's
        ///payer.
        ///</summary>
        /// <param name="mbrPayment"> </param>
        /// <param name="welcomeCallIndex"> </param>
        /// <param name="subject"> </param>
        /// <param name="ttl"> </param>
        public async Task<ulong> Bind(PaymentTransaction mbrPayment, ulong welcomeCallIndex, byte[] subject, ulong ttl, Account _tx_sender, ulong? _tx_fee, string _tx_note = "", ulong _tx_roundValidity = 1000, List<BoxRef>? _tx_boxes = null, List<Transaction>? _tx_transactions = null, List<ulong>? _tx_assets = null, List<ulong>? _tx_apps = null, List<Address>? _tx_accounts = null, AVM.ClientGenerator.Core.OnCompleteType _tx_callType = AVM.ClientGenerator.Core.OnCompleteType.NoOp)
        {
            _tx_boxes ??= new List<BoxRef>();
            _tx_transactions ??= new List<Transaction>();
            _tx_assets ??= new List<ulong>();
            _tx_apps ??= new List<ulong>();
            _tx_accounts ??= new List<Address>();
            _tx_transactions.AddRange(new List<Transaction> { mbrPayment });
            byte[] abiHandle = { 234, 27, 12, 110 };
            var welcomeCallIndexAbi = new AVM.ClientGenerator.ABI.ARC4.Types.UInt64(); welcomeCallIndexAbi.From(welcomeCallIndex);
            var subjectAbi = new AVM.ClientGenerator.ABI.ARC4.Types.FixedArray<AVM.ClientGenerator.ABI.ARC4.Types.Byte>(32, "byte"); subjectAbi.From(subject);
            var ttlAbi = new AVM.ClientGenerator.ABI.ARC4.Types.UInt64(); ttlAbi.From(ttl);

            var result = await base.CallApp(new List<object> { abiHandle, mbrPayment, welcomeCallIndexAbi, subjectAbi, ttlAbi }, _tx_fee: _tx_fee, _tx_callType: _tx_callType, _tx_roundValidity: _tx_roundValidity, _tx_note: _tx_note, _tx_sender: _tx_sender, _tx_transactions: _tx_transactions, _tx_apps: _tx_apps, _tx_assets: _tx_assets, _tx_accounts: _tx_accounts, _tx_boxes: _tx_boxes);
            var lastLogBytes = result.Last();
            if (lastLogBytes.Length < 4 || lastLogBytes[0] != 21 || lastLogBytes[1] != 31 || lastLogBytes[2] != 124 || lastLogBytes[3] != 117) throw new Exception("Invalid ABI handle");
            var lastLogReturnData = lastLogBytes.Skip(4).ToArray();
